package vn.rtr.aeris.operator01;
import java.util.*;
public final class Hex98Test{public static void main(String[]args){Random random=new Random(9819);int checks=0;for(int n:new int[]{0,1,2,15,255,256,4096}){byte[]b=new byte[n];random.nextBytes(b);check(b);checks++;}byte[]all=new byte[256];for(int i=0;i<256;i++)all[i]=(byte)i;check(all);checks++;for(int i=0;i<100;i++){byte[]b=new byte[random.nextInt(4097)];random.nextBytes(b);check(b);checks++;}System.out.println("{\"status\":\"PASS\",\"checks\":"+checks+",\"scope\":\"All byte values, random buffers, exact legacy encoder comparison\"}");}private static void check(byte[]b){StringBuilder legacy=new StringBuilder();for(byte x:b)legacy.append(String.format(Locale.ROOT,"%02x",x&255));String actual=Hex98.encode(b);if(!actual.equals(legacy.toString())||actual.length()!=b.length*2)throw new AssertionError("HEX_DELTA");for(int i=0;i<b.length;i++)if(Integer.parseInt(actual.substring(i*2,i*2+2),16)!=(b[i]&255))throw new AssertionError("ROUNDTRIP");}}
